from base import *
body=cap("Compact · soonest timer, with a count of the others")+compact('<span class="ring" style="--p:80%"></span><span>3:12</span><span class="pill" style="height:16px;padding:0 6px;font-size:10px">+1</span>','<span>Pasta</span>')
row=lambda n,p,t:f'<div style="display:flex;align-items:center;gap:12px;padding:7px 10px;border-radius:9px;background:rgba(255,255,255,.07);margin-bottom:6px;font-size:13px"><span class="ring" style="--p:{p}%"></span><b style="width:120px">{n}</b><span style="font-variant-numeric:tabular-nums;font-size:15px">{t}</span><span style="flex:1"></span><span class="pill">+1 min</span><span class="pill">■</span></div>'
inner=row("Pasta",80,"3:12")+row("Laundry",15,"24:50")+'<div style="display:flex;gap:6px;margin-top:6px;align-items:center"><span class="pill main">+ New timer</span><span class="pill" style="width:140px;color:rgba(255,255,255,.45)">Name…</span><span class="pill">5</span><span class="pill">10</span><span class="pill">25</span><span class="pill">Custom</span></div>'
body+=cap("Open notch · Timer page with several timers")+opened(inner,h=190,tabs='<span>♫</span><span class="on">◷</span>')
body+=cap("Peek · one of them is done (others keep running)")+compact('<span class="ring" style="--p:15%"></span><span>24:50</span>','',peek='<span>Pasta is done</span><span style="display:flex;gap:6px"><span class="pill" style="height:18px">+1 min</span><span class="pill main" style="height:18px">Stop</span></span>',h_scene=96)
open("m10.html","w").write(page("Timer: several named timers at once","Name timers and run them side by side, like the phone’s Timers list.",body))
